INSERT INTO `dev_item` VALUES (2,0,'STS-293',NULL,'','Story',NULL,13,'Done',0,'Sprint-7',NULL,NULL,'STS Singapore use – Analysis','Design Document, Physical architecture diagram, Logical architecture diagram, sequence of stories for application development.',NULL,NULL,NULL,'STS','Medium',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:50:28'),(3,0,'STS-350',NULL,'','Story',NULL,0,'Closed',0,NULL,NULL,NULL,'STS Singapore - Effort estimate',NULL,NULL,NULL,NULL,'STS','Medium',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:51:04'),(4,0,'STS-342',NULL,'','Story',NULL,13,'Inprogress',0,'Sprint-8',NULL,NULL,'External STS - Scanner application - Accessibility','Check availability of website in internet.',NULL,NULL,NULL,'STS','Medium',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:51:46'),(5,0,'STS-344',NULL,'','Story',NULL,5,'Ready',0,'Sprint-8',NULL,NULL,'External STS - Scanner application - Sign-In page','Design Sign-In page for Scanner.',NULL,NULL,NULL,'STS','Medium',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:52:24'),(6,0,'STS-341',NULL,'','Story',NULL,0,'Selected',0,NULL,NULL,NULL,'External STS - User Roles Matrix',NULL,NULL,NULL,NULL,'STS','Medium',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:53:01'),(7,0,'STS-318',NULL,'','Story',NULL,8,'Analysis',0,'Sprint-9',NULL,NULL,'External STS - Scanner application- Authentication','As a External STS user,\n\nI want to login the STS scanner \n\nSo that I can scan the post-exam materials barcode to send them back to Cambridge \n\nScenario: External STS user logins the STS Scanner and scan the post-exam material barcode(1. Customer Despatch Container 2. Packets inside the container) that will be sent back to Cambridge\n\nGiven that the External STS user is registered with the correct user role permission in STS AND have the correct device to scan the barcode of the post-exam materials\n\nWhen the user enters the correct User credentials in the External STS Scanner site or device  \n\nThen the user is able to login AND see the screens that are available to External users AND scan the post-exam materials barcode.','User should not be able to login with wrong username\n\nUsername will be case insensitive as current internal scanner application also follows the same.\n\nUser should not be able to login with wrong password\n\nPassword will be case sensitive.\n\nDeactivated users should not be able to login. Users should be informed on-screen about this.\n\nUser should be able to login only if all above criteria are fulfilled.\n\nAfter successful login , the user should be able to land on \"Main Menu\" page, if the user has required permission.\n\nAfter 3 successive failed login attempts, the user should be locked. Users should be informed on-screen about this. (DEV team to advise if this is feasible without complexity. From business’s point of view, this is NICE to have)\n\nA locked user should not be able to login. Users should be informed on-screen about this. (DEV team to advise if this is feasible without complexity. From business’s point of view, this is NICE to have)\n\nUsers of existing/internal STS scanner cant log into external scanner with current credentials. They need to have separate credentials.',NULL,NULL,'STS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:53:35'),(8,0,'STS-319',NULL,'','Story',NULL,8,'Analysis',0,'Sprint-9',NULL,NULL,'External STS - Scanner application_Main menu options','As a External STS user,\n\nI want to see the limited number of options (e.g. Despatch button & Find button) under the main menu in the Scanner site/device when I log in\n\nSo that I can easily identify the correct button and scan the barcode to despatch the post-exam materials back to Cambridge\n\nScenario: External STS user logins the Scanner application to scan the post-exam materials barcode to despatch back to Cambridge\n\nGiven that the External STS user is registered with the correct permission in STS and have the correct device \n\nWhen the user logs in the Scanner site or device\n\nThen the user is able to see only the limited number of options under the main menu (e.g. Despatch button & Find button) AND scan the Container barcode AND scan the script packet label barcodes to the Container barcode using the ‘Despatch’ button (which is similar to the ‘Move Items’ function in the current STS) AND find the regional script packet data using the ‘Find’ button. ','If the user has “Singapore-User“ or “Singapore-Admin“ roles , only then user can see this page.\n\nThis page should follow attached design(to be added later)\n\nThe user should see  Despatch button & Find button\n\nUser should be able to see “Container bar code scanning” page when he clicks on Despatch button\n\nUser should be able to see “Find Packet” page when he clicks on Find button\n\nUser should be able to logout from the screen using logout button.',NULL,NULL,'STS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:54:12'),(9,0,'STS-349',NULL,'','Story',NULL,13,'Ready',0,NULL,NULL,NULL,'External STS - Scanner application- Find Page','User to find only Packets and Containers belonging to Singapore centres.',NULL,NULL,NULL,'STS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:54:53'),(10,0,'STS-360',NULL,'','Story',NULL,0,'Closed',0,NULL,NULL,NULL,'Internal STS - Scanner application - Find Page',NULL,NULL,NULL,NULL,'STS','Medium',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:55:27'),(11,0,'STS-347',NULL,'','Story',NULL,8,'Analysis',0,NULL,NULL,NULL,'External STS - Scanner application - Container Barcode Scan','IF Container not closed then it can be scanned again.',NULL,NULL,NULL,'STS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:56:05'),(12,0,'STS-348',NULL,'','Story',NULL,13,'Analysis',0,NULL,NULL,NULL,'External STS - Scanner application - Packet Bar code Scan','Previously scanned packet bar codes with DC status, can be scanned again for another container provided both the containers are not closed and status of the packet will remain DC',NULL,NULL,NULL,'STS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:56:45'),(13,0,'STS-359',NULL,'','Story',NULL,5,'Analysis',0,NULL,NULL,NULL,'Internal STS - Scanner application - Singapore Packet Bar code Scan',NULL,NULL,NULL,NULL,'STS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:57:11'),(14,0,'STS-343',NULL,'','Story',NULL,5,'Analysis',0,'Sprint-9',NULL,NULL,'External STS - STS application - Accessibility','Check availability of website in internet.',NULL,NULL,NULL,'STS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:57:41'),(15,0,'STS-345',NULL,'','Story',NULL,3,'Analysis',0,NULL,NULL,NULL,'External STS - STS application - Sign-In page',NULL,NULL,NULL,NULL,'STS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:58:07'),(16,0,'STS-323',NULL,'','Story',NULL,0,'Selected',0,NULL,NULL,NULL,'External STS - STS application_User Management',NULL,NULL,NULL,NULL,'STS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:58:41'),(17,0,'STS-321',NULL,'','Story',NULL,0,'Selected',0,NULL,NULL,NULL,'External STS - Singapore User - STS Application_Authentication',NULL,NULL,NULL,NULL,'STS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 07:59:07'),(18,0,'STS-354',NULL,'','Story',NULL,8,'Analysis',0,NULL,NULL,NULL,'External STS - STS application - Authentication',NULL,NULL,NULL,NULL,'STS','5',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 08:21:42'),(19,0,'STS-358',NULL,'','Story',NULL,3,'Analysis',0,NULL,NULL,NULL,'External STS - STS application - Left menu options, Header and Footer',NULL,NULL,NULL,NULL,'STS','5',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 08:22:31'),(20,0,'STS-355',NULL,'','Story',NULL,8,'Analysis',0,NULL,NULL,NULL,'External STS - STS application - Home page',NULL,NULL,NULL,NULL,'STS','5',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 08:23:13'),(21,0,'STS-357',NULL,'','Story',NULL,8,'Analysis',0,NULL,NULL,NULL,'External STS - STS application - User Management page',NULL,NULL,NULL,NULL,'STS','5',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 08:23:51'),(22,0,'STS-356',NULL,'','Story',NULL,8,'Ready',0,NULL,NULL,NULL,'External STS - STS application - Packet Search page',NULL,NULL,NULL,NULL,'STS','5',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 08:24:40'),(23,0,'STS-320',NULL,'','Story',NULL,0,'Selected',0,NULL,NULL,NULL,'External STS - STS application_Home/Packet sections',NULL,NULL,NULL,NULL,'STS','5',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 08:25:26'),(24,0,'STS-322',NULL,'','Story',NULL,13,'Ready',0,NULL,NULL,NULL,'External STS - STS application_Reconciliation',NULL,NULL,NULL,NULL,'STS','5',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 08:26:11'),(25,0,'STS-324',NULL,'','Story',NULL,0,'Selected',0,NULL,NULL,NULL,'External STS - Packet workflow (new packet status)',NULL,NULL,NULL,NULL,'STS','5',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 08:26:47'),(26,0,'STS-325',NULL,'','Story',NULL,0,'Selected',0,NULL,NULL,NULL,'External STS - (new concept) Container',NULL,NULL,NULL,NULL,'STS','5',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 08:27:34'),(27,0,'STS-404',NULL,'','Story',NULL,5,'Analysis',0,NULL,NULL,NULL,'Internal STS - Automation application - Axiom',NULL,NULL,NULL,NULL,'STS','5',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 08:28:07'),(28,0,'STS-405',NULL,'','Story',NULL,3,'Analysis',0,NULL,NULL,NULL,'https://svn-dn.ucles.org.uk/svn/',NULL,NULL,NULL,NULL,'STS','5',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 08:28:30'),(29,0,'STS-315',NULL,'','Story',NULL,8,'Blocked',0,'Sprint-8',NULL,NULL,'Re PR2786 - Creating New Examiner Barcodes','User Story:\n\nAs a Post Exam Operations user I want to be able to create an Examiner Type barcode in the All Examiners Area on the STS application.\n\nScenario: \n\nA Post Exam Operations user is required to despatch a packet to an examiner which does not have an examiner barcode on STS.\n\nGiven that the examiner is not allocated to the packet and isn’t present in the UI then the user can click New and choose Examiner from the Type drop down.','The changes should be applicable for both Scoris and non-Scoris packets.\n\nThe changes should be applicable to allow  all Post Examinations User roles (i.e. Picker, Supervisor 1, Supervisor 2) in STS to search and create examiners as mentioned in Acceptance Criteria-3.\n\nIf the searched examiner is not allocated to a packet and also not available in the list of available examiners under All Examiners, the changes would allow to create the same examiner as Examiner Type barcode area in STS.\n\nWhile packets are searched for the updated examiners, it should show it under Barcode Location with the Examiner location details.\nPackets can be also moved via Administrator roles to basket and then to the respective examiners under All Examiners in STS.\n\nPackets should be able to Move or Redirect/Dispatch through to these newly added EXAMINERS in Scanner.',NULL,NULL,'STS','5',NULL,NULL,NULL,NULL,NULL,'Bappa',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','2020-01-20 10:32:09'),(30,0,'STS-402','STS-406','','Sub Task',NULL,0,'Ready',0,'Sprint-8',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,'Munshi','Amit',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-20 10:32:59'),(32,0,'STS-406',NULL,'','Story',NULL,0,'Ready',0,'Sprint-9',NULL,NULL,'Authentication Mechanism PoC',NULL,NULL,NULL,NULL,'STS','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'STS Singapore','2020-01-20 14:01:59'),(33,0,'STS-146',NULL,'','Story',NULL,0,'Inprogress',0,'Sprint-9',NULL,NULL,'QA1 STS build ref SR203962','this is required to enable SAP Testing in QA1. \n\nHere is what Keith Galbraith has found:\n\nThe Cognizant produced current build document for STS for QA1, This seems to be based on Windows 2008 R2 currently. \nhttps://cambridgeassessment.sharepoint.com/:w:/s/Environments/EU_pTk8ZOMhFjCxKKJz3nikBTA9qGPnNGO1pQnCEDe6ivQ?e=1uWRy0\n\nThe Cognizant document lists the following servers in it.\n\nAPP Servers (all W2k8) App Server (these are built)\nSQSTSAP401,  \nSQSTSAP402, \nSQSTSAP403, \nSQSTSAP404, \nSQSTSAP405, \nDB Server\nUQSTSOR401 (this is available)\nFTP Server\nUQSTSFT401 (this is also available)\n\nThe CMDB matches the above\n\nKeith is happy to help the team to try and get this working and arrange any access SAP and the STS team need. ',NULL,NULL,NULL,'','Medium',NULL,NULL,NULL,NULL,NULL,'Produyt',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-21 08:19:38'),(34,0,'STS-156','STS-146','','Sub Task',NULL,0,'Done',0,'Sprint-8',NULL,NULL,'Troubleshoot QA1 integration',NULL,NULL,NULL,NULL,'STS','',NULL,NULL,NULL,NULL,NULL,'Produyt',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-21 08:23:10'),(35,0,'STS-157','STS-146','','Sub Task',NULL,0,'Done',0,'Sprint-8',NULL,NULL,'Sanity test (integration points) - Developer - Java Sprint - 1',NULL,NULL,NULL,NULL,'STS','',NULL,NULL,NULL,NULL,NULL,'Produyt',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-21 08:24:09'),(36,0,'STS-163','STS-146','','Sub Task',NULL,0,'Done',0,'Sprint-8',NULL,NULL,'Sanity test (integration points) - Tester - Java - Sprint 1',NULL,NULL,NULL,NULL,'STS','',NULL,NULL,NULL,NULL,NULL,'Produyt',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-21 08:24:59'),(37,0,'STS-174','STS-146','','Sub Task',NULL,0,'Inprogress',0,'Sprint-8',NULL,NULL,'Sanity test (integration points) - Developer - Java Sprint - 2',NULL,NULL,NULL,NULL,'STS','',NULL,NULL,NULL,NULL,NULL,'Produyt',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-21 08:26:03'),(38,0,'STS-175','STS-146','','Sub Task',NULL,0,'Blocked',0,'Sprint-8',NULL,NULL,'Sanity test (integration points) - Tester - Java - Sprint 2',NULL,NULL,NULL,NULL,'STS','',NULL,NULL,NULL,NULL,NULL,'Prodyut','Amit',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-21 08:27:06'),(39,0,'EE-94',NULL,'','Story',NULL,5,'Inprogress',0,'Sprint-8',NULL,NULL,'Review Discovery Document & Breakdown of Next Activities for EE Platform Upgrade',NULL,'Discovery undertaken under separate ADSO (discovery report attached to EE-86: Entries Extranet UpgradeNEW) -  Development team would go through the discovery document to grab the context of the work related to platform upgrade.\n\nThis would help in flaring up the relevant Epic & stories to refine, estimate and form the logical sequence of platform upgrade in future sprints.\n\nThe upgrade is required to satisfy Cyber Essentials, hence the high priority.',NULL,NULL,'','',NULL,NULL,NULL,NULL,NULL,'Munshi',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-21 08:29:28'),(40,0,'EE-95','EE-94','','Sub Task',NULL,0,'Done',0,'Sprint-8',NULL,NULL,'Understand/Review the context of the document.',NULL,NULL,NULL,NULL,'','',NULL,NULL,NULL,NULL,NULL,'Munshi',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-21 08:30:40'),(41,0,'EE-96','EE-94','','Sub Task',NULL,0,'Done',0,'Sprint-8',NULL,NULL,'Breakdown of the tasks along with estimates.',NULL,NULL,NULL,NULL,'','',NULL,NULL,NULL,NULL,NULL,'Munshi',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-21 08:31:40'),(43,0,'CER-463',NULL,'','Task',NULL,0,'Inprogress',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-21 10:33:04'),(44,0,'CER-434',NULL,'','Story',NULL,3,'Ready',0,'Sprint-8',NULL,NULL,'RVS URN (CR834) Java PP2/Prod Deploy Instruction','Provide RVS URN Java Production Deploy instructions, to include :-\n\nPhysical instruction to enable deploy\n\nInstruction for any pre-reqs eg firewalls, server set up, permissions etc.\n\nExact prod deploy date TBC but likely to be Sprint 9. Front load these deploy tasks in Sprint 8 so can do any environment changes early (eg permissions, firewalls, etc) and test before the actual go live.\n\nDeploy code artefacts can be provided later in the sprint/early sprint 9.',NULL,NULL,NULL,'RVS','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','2020-01-22 07:47:35'),(45,0,'CER-280',NULL,'','Story',NULL,5,'Inprogress',0,'Sprint-8',NULL,NULL,'Format on-screen messages','Description\n\nUser Story\nAs a Cambridge English admin \nI want to be able to format the message I post on the system \nSo that I can communicate effectively with users of the system, ','Admin user can format an on-screen message for ROs with:\n\nHyperlinks\n\nBold text\n\nItalic text\n\nBullet points\n\nNumbered lists\n\nText colour',NULL,NULL,'','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-22 07:52:29'),(46,0,'CER-457','CER-434','','Sub Task',NULL,0,'Done',0,'Sprint-8',NULL,NULL,'PRD Deployment Artefacts and Instructions',NULL,NULL,NULL,NULL,'','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-22 08:01:54'),(47,0,'CER-456','CER-434','','Sub Task',NULL,0,'Done',0,'Sprint-8',NULL,NULL,'PP2 Deployment Artefacts and Instructions',NULL,NULL,NULL,NULL,'','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-22 08:02:45'),(48,0,'STS-381','STS-342','','Incident',NULL,0,'Done',0,'Sprint-8',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','',NULL,NULL,NULL,NULL,NULL,'Munshi',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-22 08:04:42'),(49,0,'STS-382','STS-342','','Sub Task',NULL,0,'Done',0,'Sprint-8',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','',NULL,NULL,NULL,NULL,NULL,'Munshi',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-22 08:05:33'),(50,0,'STS-383','STS-342','','Sub Task',NULL,0,'Done',0,'Sprint-8',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','',NULL,NULL,NULL,NULL,NULL,'Munshi',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-01-22 08:06:04'),(51,0,'STS-385','STS-342','','Sub Task',NULL,0,'Done',0,'Sprint-8',NULL,