,NULL),(170,737582,'Incident','STS not loading',NULL,'Closed','STS not loading(authorization issue)','Alamgir Ali SK',NULL,'2020-01-16 16:28:53','2020-01-17 17:05:00','2020-01-20 10:58:57','STS',4,'N',0,'N','N','N','Not fault found,but according to log HTTP/1.1\" 401 found which is unauthorised access.',NULL,'Java','N',' ',NULL,'','','Operational','Unavoidable','Automate',NULL,'LDAP was not working','2020-02-04 08:02:49',NULL,NULL),(171,229217,'Service Request','EPS Request: Miscellaneous',NULL,'Fulfilled','Customer requested to investigate entries for CI CheckPoint qualification where the candidate\'s data of birth was null. CI require that all CheckPoint candidate entries in CI DIRECT have a candidate birth date.','Pralaysankar Saha',NULL,'2020-01-15 16:30:31',NULL,'2020-01-20 11:02:44','CIE Direct',5,'N',0,'N','N','N',NULL,NULL,'Java','N',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(172,737710,'Incident','STS PRD SCANNER spstsap003 is DOWN(authorization issue)',NULL,'Resolved','STS PRD SCANNER spstsap003 is DOWN(authorization issue)','Alamgir Ali SK',NULL,'2020-01-16 16:36:00','2020-01-17 16:36:00','2020-01-20 11:07:00','STS',4,'N',0,'N','N','N','Not a valid incident .Scanner spstsap004 is up now. Incident is raised from internal service and it is not a valid server down problem. Status code found 401 in server log file.',NULL,'Java','N',NULL,NULL,NULL,NULL,'Operational','Unavoidable','Automate',NULL,'LDAP was not working','2020-02-04 08:02:35',NULL,NULL),(173,736881,'Incident','Issue with uploading CSV file on Direct',NULL,'Resolved','Centre CN214 is trying to upload CSV file with candidate\'s details using ‘Add Candidates from Spreadsheet’ screen on Cambridge International Direct (Exam series: June 2020)\n\nHowever, there is an error message each time centre tries to upload the file. Customer had reviewed the CSV file but they could not locate any issue.\nCustomer want to know the issue behind that.','Pralaysankar Saha',NULL,'2020-01-14 15:53:1